(()=>{
function updateErrorHierarchy(){const panel=document.getElementById('data-errors');if(!panel)return;const source=document.getElementById('data-error-count'),raw=source.textContent,match=raw.match(/(\d+)\s*类\s*·\s*(\d+)\s*项/),coverage=raw.match(/数据覆盖率\s*(\d+%)/);let summary=panel.querySelector('.error-summary');if(!summary){source.classList.add('error-source-summary');summary=document.createElement('div');summary.className='error-summary';summary.setAttribute('aria-hidden','true');summary.innerHTML='<div><strong data-error-items>0</strong>项待处理 · <span data-error-groups>0</span> 类</div><small>数据覆盖率 <span data-error-coverage></span></small>';panel.querySelector(':scope>.section-head').append(summary)}summary.querySelector('[data-error-items]').textContent=match?.[2]||'0';summary.querySelector('[data-error-groups]').textContent=match?.[1]||'0';summary.querySelector('[data-error-coverage]').textContent=coverage?.[1]||'未知';
panel.querySelectorAll('.data-group-header').forEach(row=>{const note=row.querySelector('.note');if(!note)return;const text=note.textContent,parts=text.match(/^(\d+)\s*项\s*·\s*/);if(!parts)return;let count=row.querySelector('.error-group-count');if(!count){count=document.createElement('span');count.className='error-group-count';row.querySelector('b').after(count)}count.textContent=parts[1]+' 项';const prefix=document.createElement('span');prefix.className='error-count-prefix';prefix.setAttribute('aria-hidden','true');prefix.textContent=parts[0];const impact=document.createElement('span');impact.textContent=text.slice(parts[0].length);note.replaceChildren(prefix,impact)});
const cell=panel.querySelector('tr[data-count] td:first-child');if(cell&&!cell.querySelector('.error-state-id')){const raw=cell.textContent,index=raw.indexOf('（');if(index>=0){cell.replaceChildren(document.createTextNode(raw.slice(0,index)));const id=document.createElement('span');id.className='error-state-id';id.textContent=raw.slice(index);cell.append(id)}}}
const previousRender=render;render=function(){previousRender();updateErrorHierarchy()};const previousFilters=applyFilters;applyFilters=function(){previousFilters();updateErrorHierarchy()};updateErrorHierarchy();
})();
